import { Controller, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const SYSTEM_TYPES = ['ERP', '그룹웨어'];
const USE_YN = ['사용', '미사용'];

function fail(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function textOf(value: unknown, label: string, max: number): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw fail(label + ' 형식이 올바르지 않습니다.');
  }
  if (value.length > max) {
    throw fail(label + '은(는) ' + max + '자 이내로 입력해 주세요.');
  }
  return value;
}

function intOf(value: unknown, label: string): number | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value === 'number' && Number.isInteger(value)) {
    return value;
  }
  if (typeof value === 'string' && /^-?\d+$/.test(value.trim())) {
    return Number(value.trim());
  }
  throw fail(label + '은(는) 정수여야 합니다.');
}

@Controller('api/v1')
export class FnSfr02603Controller {
  @Post('/menus')
  @HttpCode(200)
  async createMenu(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const name = textOf(data['name'], '메뉴명', 100);
    if (name === null) {
      throw fail('메뉴명을 입력해 주세요.');
    }
    const systemType = data['systemType'];
    if (typeof systemType !== 'string' || !SYSTEM_TYPES.includes(systemType)) {
      throw fail('적용 시스템 구분은 ERP 또는 그룹웨어여야 합니다.');
    }
    const useYn = data['useYn'];
    if (typeof useYn !== 'string' || !USE_YN.includes(useYn)) {
      throw fail('사용 여부는 사용 또는 미사용이어야 합니다.');
    }
    const parentMenuId = intOf(data['parentMenuId'], '상위 메뉴');
    const sortOrder = intOf(data['sortOrder'], '정렬 순서');
    const moduleLink = textOf(data['moduleLink'], '연결 모듈', 200);
    return transaction(async (db) => {
      if (parentMenuId !== null) {
        const parents = await db.query(
          'SELECT menu_id FROM menu WHERE menu_id = CAST(:parentMenuId AS bigint)',
          { parentMenuId },
        );
        if (parents.length === 0) {
          throw new ApiError(404, 'PARENT_MENU_NOT_FOUND', '상위 메뉴가 존재하지 않습니다.');
        }
      }
      const rows = await db.query(
        'INSERT INTO menu (parent_menu_id, name, system_type, module_link, sort_order, use_yn, created_at, updated_at) ' +
          'VALUES (CAST(:parentMenuId AS bigint), :name, :systemType, :moduleLink, CAST(:sortOrder AS integer), :useYn, now(), now()) ' +
          'RETURNING menu_id AS "menuId"',
        { parentMenuId, name, systemType, moduleLink, sortOrder, useYn },
      );
      return { menuId: Number(rows[0]['menuId']) };
    });
  }

  @Patch('/menus/:menuId')
  async updateMenu(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const menuIdText = req.params['menuId'];
    if (!/^\d+$/.test(menuIdText)) {
      throw new ApiError(404, 'MENU_NOT_FOUND', '메뉴가 존재하지 않습니다.');
    }
    const name = textOf(data['name'], '메뉴명', 100);
    if (data['name'] !== undefined && data['name'] !== null && name === null) {
      throw fail('메뉴명을 입력해 주세요.');
    }
    const useYnRaw = data['useYn'];
    let useYn: string | null = null;
    if (useYnRaw !== undefined && useYnRaw !== null && useYnRaw !== '') {
      if (typeof useYnRaw !== 'string' || !USE_YN.includes(useYnRaw)) {
        throw fail('사용 여부는 사용 또는 미사용이어야 합니다.');
      }
      useYn = useYnRaw;
    }
    const parentMenuId = intOf(data['parentMenuId'], '상위 메뉴');
    const sortOrder = intOf(data['sortOrder'], '정렬 순서');
    const moduleLink = textOf(data['moduleLink'], '연결 모듈', 200);
    if (name === null && useYn === null && parentMenuId === null && sortOrder === null && moduleLink === null) {
      throw fail('수정할 항목을 입력해 주세요.');
    }
    if (parentMenuId !== null && String(parentMenuId) === menuIdText) {
      throw fail('자기 자신을 상위 메뉴로 지정할 수 없습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT menu_id FROM menu WHERE menu_id = CAST(:menuId AS bigint)',
        { menuId: menuIdText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'MENU_NOT_FOUND', '메뉴가 존재하지 않습니다.');
      }
      if (parentMenuId !== null) {
        const parents = await db.query(
          'SELECT menu_id FROM menu WHERE menu_id = CAST(:parentMenuId AS bigint)',
          { parentMenuId },
        );
        if (parents.length === 0) {
          throw new ApiError(404, 'PARENT_MENU_NOT_FOUND', '상위 메뉴가 존재하지 않습니다.');
        }
      }
      const rows = await db.query(
        'UPDATE menu SET ' +
          'name = COALESCE(CAST(:name AS varchar), name), ' +
          'parent_menu_id = COALESCE(CAST(:parentMenuId AS bigint), parent_menu_id), ' +
          'module_link = COALESCE(CAST(:moduleLink AS varchar), module_link), ' +
          'sort_order = COALESCE(CAST(:sortOrder AS integer), sort_order), ' +
          'use_yn = COALESCE(CAST(:useYn AS varchar), use_yn), ' +
          'updated_at = now() ' +
          'WHERE menu_id = CAST(:menuId AS bigint) ' +
          'RETURNING menu_id AS "menuId"',
        { menuId: menuIdText, name, parentMenuId, moduleLink, sortOrder, useYn },
      );
      return { menuId: Number(rows[0]['menuId']) };
    });
  }
}

