import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SYSTEM_OPTIONS: [string, string][] = [
  ['ERP', 'ERP'],
  ['그룹웨어', '그룹웨어'],
];

const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

export default function FnSfr02603Page({ role, notify }: PageProps) {
  const [systemType, setSystemType] = useState('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const [name, setName] = useState('');
  const [newSystemType, setNewSystemType] = useState('');
  const [parentMenuId, setParentMenuId] = useState<number | string>('');
  const [moduleLink, setModuleLink] = useState('');
  const [sortOrder, setSortOrder] = useState<number | string>('');
  const [useYn, setUseYn] = useState('사용');

  const size = 20;
  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/menus', role, undefined, { systemType, page, size }),
    [systemType, page, role],
  );

  function resetForm(row: Row | null) {
    setName(row ? String(row['name'] ?? '') : '');
    setNewSystemType('');
    setParentMenuId(row && row['parentMenuId'] != null ? (row['parentMenuId'] as number) : '');
    setModuleLink(row && row['moduleLink'] != null ? String(row['moduleLink']) : '');
    setSortOrder(row && row['sortOrder'] != null ? (row['sortOrder'] as number) : '');
    setUseYn(row ? '' : '사용');
  }

  function openCreate() {
    resetForm(null);
    setCreating(true);
  }

  function openEdit(row: Row) {
    resetForm(row);
    setEditing(row);
  }

  async function submitCreate() {
    if (!name.trim()) {
      throw new Error('메뉴명을 입력해 주세요.');
    }
    if (!newSystemType) {
      throw new Error('적용 시스템 구분을 선택해 주세요.');
    }
    if (!useYn) {
      throw new Error('사용 여부를 선택해 주세요.');
    }
    await call('POST', '/menus', role, {
      name,
      systemType: newSystemType,
      parentMenuId,
      moduleLink,
      sortOrder,
      useYn,
    });
    notify('메뉴를 추가했습니다.');
    setCreating(false);
    reload();
  }

  async function submitEdit() {
    if (!editing) {
      return;
    }
    if (!name.trim()) {
      throw new Error('메뉴명을 입력해 주세요.');
    }
    await call('PATCH', '/menus/' + String(editing['menuId']), role, {
      name,
      parentMenuId,
      moduleLink,
      sortOrder,
      useYn,
    });
    notify('메뉴를 수정했습니다.');
    setEditing(null);
    reload();
  }

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  const columns = [
    { key: 'name', label: '메뉴명' },
    { key: 'systemType', label: '적용 시스템 구분' },
    {
      key: 'parentMenuId',
      label: '상위 메뉴',
      render: (row: Row) =>
        row['parentMenuId'] != null ? (
          <RefName table="menu" role={role} value={row['parentMenuId']} />
        ) : (
          '-'
        ),
    },
    { key: 'moduleLink', label: '연결 모듈' },
    {
      key: 'sortOrder',
      label: '정렬 순서',
      render: (row: Row) => <Num value={row['sortOrder']} />,
    },
    {
      key: 'menuId',
      label: '관리',
      render: (row: Row) => (
        <button type="button" onClick={() => openEdit(row)}>
          수정
        </button>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-3">
        <h2>전체 메뉴</h2>
        <Num value={total} />
      </section>
      <section className="box span-12">
        <h2>포털 메뉴</h2>
        <Filters
          onSearch={() => setPage(0)}
          onReset={() => {
            setSystemType('');
            setPage(0);
          }}
        >
          <Field label="적용 시스템 구분">
            <Select
              value={systemType}
              onChange={(v) => {
                setSystemType(v);
                setPage(0);
              }}
              options={SYSTEM_OPTIONS}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>
            메뉴 추가
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable columns={columns} rows={rows} empty="등록된 메뉴가 없습니다." />
        <Pager page={page} size={size} total={total} onPage={setPage} />
      </section>

      {creating ? (
        <Drawer title="메뉴 추가" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="추가">
            <Field label="메뉴명" required>
              <TextInput value={name} onChange={setName} />
            </Field>
            <Field label="적용 시스템 구분" required>
              <Select value={newSystemType} onChange={setNewSystemType} options={SYSTEM_OPTIONS} />
            </Field>
            <Field label="상위 메뉴">
              <LookupSelect
                table="menu"
                role={role}
                value={parentMenuId}
                onChange={setParentMenuId}
                placeholder="최상위 메뉴"
              />
            </Field>
            <Field label="연결 모듈">
              <TextInput value={moduleLink} onChange={setModuleLink} />
            </Field>
            <Field label="정렬 순서">
              <NumberInput value={sortOrder} onChange={setSortOrder} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {editing ? (
        <Drawer title="메뉴 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="저장">
            <Field label="메뉴명" required>
              <TextInput value={name} onChange={setName} />
            </Field>
            <Field label="상위 메뉴">
              <LookupSelect
                table="menu"
                role={role}
                value={parentMenuId}
                onChange={setParentMenuId}
                placeholder="선택"
              />
            </Field>
            <Field label="연결 모듈">
              <TextInput value={moduleLink} onChange={setModuleLink} />
            </Field>
            <Field label="정렬 순서">
              <NumberInput value={sortOrder} onChange={setSortOrder} />
            </Field>
            <Field label="사용 여부" hint="비워 두면 변경하지 않습니다.">
              <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} placeholder="변경 안 함" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
